mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.RG_DT DESC) AS LISTNUM, PRCDOC_UNQ_KY_VAL, DIVS_CD, PPCD, PRCDOC_CFY, PRCDOC_NO, PRCDOC_NM, DOC_TYP, DOC_PART_NO, RRD_CFY, PRCDOC_RVSN_NO, ATCT_NM, FNCLC_ID, REGPR_ID, REGPR_NM, RG_DT, FRM_UNQ_KY_VAL, MNTRG_YN, TO_CHAR(RG_DT, 'YYYY-MM-DD') AS FM_RG_DT, (SELECT count(*) FROM GE_MP_FRM1_M WHERE FRM_UNQ_KY_VAL = A.FRM_UNQ_KY_VAL) FRM_CNT, (SELECT count(*) FROM GE_MP_FRMID_M WHERE FRM_UNQ_KY_VAL = A.FRM_UNQ_KY_VAL) FRMID_CNT, (SELECT count(*) FROM GE_MP_QR_M WHERE PRCDOC_UNQ_KY_VAL = A.PRCDOC_UNQ_KY_VAL) QR_CNT FROM GE_MP_PRCDOC_M A WHERE DLT_YN = 'N'
AND A.PPCD = #{PPCD}
AND A.PRCDOC_CFY = #{PRCDOC_CFY}
AND A.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND A.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
ORDER BY RG_DT DESC ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

SELECT COUNT(*) FROM GE_MP_PRCDOC_M A WHERE DLT_YN = 'N'
AND A.PPCD = #{PPCD}
AND A.PRCDOC_CFY = #{PRCDOC_CFY}
AND A.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND A.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'

mapper.update:
UPDATE GE_MP_PRCDOC_M
   SET PRCDOC_RVSN_NO 	 = #{PRCDOC_RVSN_NO},
       FRM_UNQ_KY_VAL 	 = #{FRM_UNQ_KY_VAL}
 WHERE PRCDOC_UNQ_KY_VAL = #{PRCDOC_UNQ_KY_VAL}
